const statuses=['înregistrată','acceptată','în preparare','gata','finalizată'];

function DishPhoto({dish,className='',sizes='(max-width: 767px) 46vw, (max-width: 899px) 31vw, 24vw'}:{dish:Dish;className?:string;sizes?:string}){if(!dish.image)return <BeverageVisual dish={dish}/>;const responsive=(dish.image?.startsWith('./images/menu-complete/')||dish.image?.startsWith('./assets/media-'))&&(dish.imageWidth||0)>480;return <img className={[className,['cm-2','cm-4','cm-108'].includes(dish.id)?'dish-photo-approved':''].filter(Boolean).join(' ')} src={dish.image} srcSet={responsive?dish.image!.replace('.webp','-480.webp')+' 480w, '+dish.image+' '+dish.imageWidth+'w':undefined} sizes={responsive?sizes:undefined} alt={dish.name} loading="lazy" decoding="async" width={dish.imageWidth||640} height={dish.imageHeight||640}/>}

function Modal({title,children,onClose,wide=false,className=''}:{title:string;children:React.ReactNode;onClose:()=>void;wide?:boolean;className?:string}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement;const old=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const nodes=ref.current?.querySelectorAll<HTMLElement>('button,a[href],input,select,textarea,[tabindex="0"]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===ref.current)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',key);previous?.focus();};},[]);return <div className="modal-overlay" onClick={e=>{if(e.target===e.currentTarget)onClose()}}><div ref={ref} className={'modal '+(wide?'wide':'')+' '+className} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1}><div className="modal-head"><span className="eyebrow">CASA MIA BY OANA</span><button className="icon-button" onClick={onClose} aria-label="Închide"><X/></button></div>{children}</div></div>}
export default function Home(){
 const commerce=useCommerce();const [quote,setQuote]=useState<Quote|null>(null);const [zone,setZone]=useState('');
 const availability=useMenuAvailability();
 const [checkoutDraft,setCheckoutDraft]=useState<CheckoutDraft>(emptyCheckoutDraft);
 const headerRef=useRef<HTMLElement>(null);
 const [eventOccasion,setEventOccasion]=useState<EventOccasion>('cununie');
 const [heroTarget,setHeroTarget]=useState<{id:string}|null>(null);
 const [menuKind,setMenuKind]=useState<'food'|'drinks'>('food');const [originalKind,setOriginalKind]=useState<OriginalKind>('restaurant');
 const [cart,setCart]=useState<Cart>({});const [loaded,setLoaded]=useState(false);const [category,setCategory]=useState('Specialitățile casei');const [query,setQuery]=useState('');const [product,setProduct]=useState<Dish|null>(null);const [qty,setQty]=useState(1);const [panel,setPanel]=useState<'cart'|'reservation'|'orders'|'gallery'|'event-menus'|null>(null);const [mobileNav,setMobileNav]=useState(false);const [step,setStep]=useState(1);const [mode,setMode]=useState('ridicare');const [toast,setToast]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [order,setOrder]=useState<Order|null>(null);const [history,setHistory]=useState<Order[]>([]);const [reserveKind,setReserveKind]=useState('masă');const [reserved,setReserved]=useState(false);
 useEffect(()=>{const banner=document.querySelector<HTMLElement>('.announcement');if(!banner)return;let frame=0;const update=()=>{frame=0;document.documentElement.style.setProperty('--cm-header-top',Math.max(0,banner.getBoundingClientRect().bottom)+'px')};const schedule=()=>{if(!frame)frame=requestAnimationFrame(update)};update();window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);const observer=new ResizeObserver(schedule);observer.observe(banner);return()=>{cancelAnimationFrame(frame);observer.disconnect();window.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule)}} ,[]);
 useEffect(()=>{try{const raw=JSON.parse(localStorage.getItem('cm-preview-cart')||'{}');const clean:Cart={};for(const d of menu){if(Number.isInteger(raw[d.id])&&raw[d.id]>0&&raw[d.id]<=20)clean[d.id]=raw[d.id];}setCart(clean);}catch{}setLoaded(true);},[]);
 useEffect(()=>{if(loaded)localStorage.setItem('cm-preview-cart',JSON.stringify(cart));},[cart,loaded]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),2800);return()=>clearTimeout(timer);},[toast]);
 useEffect(()=>{if(!order?.id)return;const refresh=()=>fetch('/api/orders/'+order.id).then(r=>r.ok?r.json() as Promise<Order>:null).then(d=>{if(d)setOrder(d)}).catch(()=>{});const timer=setInterval(refresh,10000);return()=>clearInterval(timer);},[order?.id]);
 useEffect(()=>{if(!heroTarget)return;const frame=requestAnimationFrame(()=>{const target=document.getElementById('dish-'+heroTarget.id);if(!target)return;target.focus({preventScroll:true});target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});return()=>cancelAnimationFrame(frame);},[heroTarget]);
 function goToHeroDish(d:Dish){setMenuKind('food');setCategory(d.category);setQuery('');setMobileNav(false);setHeroTarget({id:d.id});}
 const lines=menu.filter(d=>cart[d.id]);const count=lines.reduce((n,d)=>n+cart[d.id],0);const total=lines.reduce((n,d)=>n+Math.round(d.price*100)*cart[d.id],0)/100;
 const deliveryEligible=total*100>=serviceRules.deliveryMinimumCents;const payable=cartTotals(Math.round(total*100),mode,count).total/100;
 const shown=foodMenu.filter(d=>(category==='Toate categoriile'||d.category===category)&&normalize(d.name+' '+d.ingredients).includes(normalize(query)));
 function change(id:string,delta:number){if(delta>0&&availability[id]===false)return;setCart(c=>{const n={...c};const q=Math.max(0,Math.min(20,(n[id]||0)+delta));if(q)n[id]=q;else delete n[id];return n;});}
 function add(d:Dish,n=1){if(availability[d.id]===false){setToast('Acest preparat este indisponibil momentan.');return;}setCart(c=>({...c,[d.id]:Math.min(20,(c[d.id]||0)+n)}));setToast(d.name+' — adăugat în coș');}
 function openCart(){setPanel('cart');setStep(1);setError('');setMobileNav(false)}
 function openReserve(kind='masă'){setReserveKind(kind);setReserved(false);setError('');setPanel('reservation');setMobileNav(false)}
 async function openOrders(){setPanel('orders');setError('');setBusy(true);try{const r=await fetch('/api/orders');const data=await r.json() as {orders:Order[];error?:string};if(!r.ok)throw new Error(data.error);setHistory(data.orders);}catch(e){setError(e instanceof Error?e.message:'Nu am putut încărca comenzile.')}finally{setBusy(false)}}
 async function checkout(){setError('');if(mode==='livrare'&&!deliveryEligible){setError('Comanda minimă pentru livrare gratuită este 70 lei în produse.');return;}if(isDemo){setStep(2);return;}setBusy(true);try{const r=await fetch('/api/quote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,zone,items:lines.map(d=>({id:d.id,quantity:cart[d.id]}))})});const q=await r.json();if(!r.ok)throw new Error(q.error);setQuote(q);setStep(2);}catch(e){setError(e instanceof Error?e.message:'Nu am putut verifica totalul.');}finally{setBusy(false)}}
 async function submitOrder(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(mode==='livrare'&&!deliveryEligible){setError('Comanda minimă pentru livrare gratuită este 70 lei în produse.');return;}setBusy(true);setError('');const f=new FormData(e.currentTarget);try{const data=await postCommerce('/api/orders',{name:f.get('name'),phone:f.get('phone'),mode,zone,address:[f.get('address'),f.get('locality')].filter(Boolean).join(', '),postalCode:f.get('postalCode')||'',notes:f.get('notes'),payment:f.get('payment'),acceptedTerms:f.get('terms')==='on',policyVersion:quote?.policyVersion,quoteToken:quote?.quoteToken,items:lines.map(d=>({id:d.id,quantity:cart[d.id]}))});setOrder(data);setCart({});setStep(3);}catch(e){setError(e instanceof Error?e.message:'Conexiunea a eșuat. Încearcă din nou.')}finally{setBusy(false)}}
 async function submitReservation(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');const f=new FormData(e.currentTarget);try{await postCommerce('/api/reservations',{name:f.get('name'),phone:f.get('phone'),date:f.get('date'),time:f.get('time'),guests:Number(f.get('guests')),kind:reserveKind,notes:f.get('notes'),acceptedTerms:f.get('terms')==='on',policyVersion:commerce.config?.policyVersion});setReserved(true);}catch(e){setError(e instanceof Error?e.message:'Nu am putut salva cererea.')}finally{setBusy(false)}}
 function openEventMenus(occasion:EventOccasion='cununie'){setEventOccasion(occasion);setPanel('event-menus');setMobileNav(false)}
 function openOriginal(kind:OriginalKind='restaurant'){setOriginalKind(kind);setPanel('gallery')}
 function choose(d:Dish){setProduct(d);setQty(1);setError('')}
 const goToMenu=useMenuArrival(()=>{setMenuKind('food');setQuery('');setMobileNav(false);setPanel(null);setHeroTarget(null)},menuKind+'|'+category+'|'+query+'|'+loaded+'|'+!!count);
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Bucharest',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 return <>
 <div className="announcement"><span className="announcement-brand">RESTAURANT & EVENTS</span><div className="top-phone-links"><a className="top-phone events-phone" href="tel:0761736599" aria-label="Sună pentru evenimente: 0761 736 599"><Heart size={20}/><span><small>Evenimente</small><strong>0761 736 599</strong></span></a><a className="top-phone restaurant-phone" href="tel:0756021501" aria-label="Sună pentru comenzi și restaurant: 0756 021 501"><UtensilsCrossed size={20}/><span><small>Comenzi & Restaurant</small><strong>0756 021 501</strong></span></a></div><SocialLinks compact className="announcement-socials"/></div>
 <header ref={headerRef} className="header"><a className="brand" href="#acasa" aria-label="Casa Mia — acasă"><img src="./images/casa-mia-header-logo.webp" srcSet="./images/casa-mia-header-logo.webp 600w, ./images/casa-mia-header-logo@2x.webp 1200w" sizes="(max-width: 560px) 118px, (max-width: 800px) 145px, 150px" alt="Casa Mia by OAna Restaurant & Events" width="1448" height="960" loading="eager" fetchPriority="high" decoding="async"/></a><nav aria-label="Navigație principală"><a href="#meniu">Meniul nostru</a><a href="#poveste">Casa Mia</a><a href="#galerie">Galerie</a><button className="event-nav-link" onClick={()=>openEventMenus()}>Meniuri evenimente</button><a href="#contact">Contact</a></nav><div className="header-actions"><button className="text-button reserve-nav" onClick={()=>openReserve()}>Rezervă o masă <ArrowUpRight size={16}/></button><button className="cart-button" onClick={openCart}><ShoppingBag size={18}/><span>{count?money(payable):'Coșul tău'}</span><b>{count}</b></button><button className="icon-button hamburger" onClick={()=>setMobileNav(!mobileNav)} aria-label="Deschide navigația" aria-expanded={mobileNav}>{mobileNav?<X/>:<MenuIcon/>}</button></div><HeaderFloralEdge/></header><div className="header-space" aria-hidden="true"/>
 {mobileNav&&<nav className="mobile-nav" aria-label="Navigație mobilă">{[['Meniul nostru','#meniu'],['Povestea Casa Mia','#poveste'],['Galerie','#galerie'],['Evenimente','#evenimente'],['Contact','#contact']].map(([s,h])=><a key={h} href={h} onClick={()=>setMobileNav(false)}>{s}<ArrowUpRight size={18}/></a>)}<button className="mobile-event-nav" onClick={()=>openEventMenus()}>Meniuri cununie · botez · parastas <ArrowUpRight size={18}/></button><button onClick={()=>openReserve()}>Rezervă o masă <CalendarDays size={18}/></button></nav>}
 <main>
 <section className="hero" id="acasa"><div className="hero-photo"><HeroDishScene onSelect={goToHeroDish}/></div><div className="hero-inner wrap"><div className="hero-copy"><div className="eyebrow"><span className="gold-line"/>BINE AI VENIT LA CASA MIA</div><h1><span>Gustul care te face</span><span>să te simți <em>acasă.</em></span></h1><p>De la pofta de ceva bun la mesele care devin amintiri. Alege-ți preparatul preferat, iar restul vine firesc.</p><div className="hero-buttons"><a className="button gold" href="#meniu"><span><strong className="cta-order-word">COMANDĂ</strong> ceva bun</span> <ArrowUpRight size={19}/><HeroButtonTrace/></a><button className="button outline" onClick={()=>openReserve()}>Rezervă o masă<HeroButtonTrace/></button></div><div className="hero-bottom"><span><UtensilsCrossed size={16}/>Restaurant</span><i/><span><Heart size={16}/>Evenimente</span><i/><span>by OAna</span></div></div></div><a href="#preferate" className="hero-scroll">MAI JOS, MAI MULT GUST <span>↓</span></a></section>
 <section className="event-menu-shortcuts" aria-label="Meniuri pentru evenimente"><div className="wrap"><div className="event-shortcut-label"><CalendarDays size={22}/><span>Meniuri pentru<br/><strong>ocazia ta</strong></span></div><div className="event-shortcut-options">{(['cununie','botez','parastas'] as EventOccasion[]).map(occasion=><button key={occasion} onClick={()=>openEventMenus(occasion)}><span>{occasion==='cununie'?'Cununie':occasion==='botez'?'Botez':'Parastas'}<small>{occasion==='parastas'?'Clasic & de post':'2 meniuri · de la 60 € / persoană'}</small></span><ArrowUpRight size={20}/></button>)}</div></div></section>
 <section className="intro-strip wrap"><div><span className="intro-number">01</span><p>Specialități cu<br/><strong>personalitate.</strong></p></div><div><span className="intro-number">02</span><p>O masă împreună.<br/><strong>O bucurie în plus.</strong></p></div><div><span className="intro-number">03</span><p>Restaurant & Events.<br/><strong>Același suflet Casa Mia.</strong></p></div></section>
 <section className="favorites section wrap" id="preferate"><div className="section-head"><div><p className="eyebrow dark">ÎNCEPE CU CEVA BUN</p><h2>Pofta are <em>preferințe.</em></h2></div><a className="underlink" href="#meniu">Vezi tot meniul <ArrowUpRight size={18}/></a></div><div className="featured-grid">{featuredNames.map((name,i)=>{const d=menu.find(d=>d.name===name)!;return <article className="featured-card" key={d.id}><button className="featured-photo" onClick={()=>choose(d)}><DishPhoto dish={d}/><span className="dish-tag">{['Specialitatea casei','Show la masă','Din mare, cu gust','Finalul dulce'][i]}</span></button><div className="featured-content"><div className="dish-meta">{d.category}<span>{d.weight}</span></div><button className="dish-title-button" onClick={()=>choose(d)}><h3>{d.name}</h3></button><div className="price-row"><strong>{money(d.price)}</strong><button className="add-button" disabled={availability[d.id]===false} onClick={()=>add(d)} aria-label={'Adaugă '+d.name}><Plus size={20}/></button></div></div></article>})}</div></section>
 <section className="order-band"><div className="wrap"><div><p className="eyebrow">POFTA TA, ÎN RITMUL TĂU</p><h2>La masă. La pachet.<br/><em>Cum îți place.</em></h2></div><div className="order-options"><a href="#meniu" onClick={()=>setMode('livrare')}><LuxuryCar size={42}/><div><h3>Livrare</h3><p>Gratuit de la 70 lei · rază 7 km.</p></div><ArrowUpRight size={23}/></a><a href="#meniu" onClick={()=>setMode('ridicare')}><PaperBag size={34}/><div><h3>Ridicare</h3><p>Comandă și ridică din restaurant.</p></div><ArrowUpRight size={23}/></a><button onClick={()=>openReserve()}><CalendarDays size={26}/><div><h3>Rezervă o masă</h3><p>Un loc pentru tine și ai tăi.</p></div><ArrowUpRight size={23}/></button></div></div></section>
 <section className="menu-section section" id="meniu"><div className="wrap"><div className="section-head"><div><p className="eyebrow dark">CEVA BUN PENTRU FIECARE POFTĂ</p><h2>Meniul <em>Casa Mia.</em></h2></div></div><button className="menu-event-direct" onClick={()=>openEventMenus()}><CalendarDays size={18}/><span>Meniuri pentru <strong>cununie, botez, parastas și evenimente speciale</strong></span><ArrowUpRight size={18}/></button></div><div className="wrap menu-arrival" id="menu-arrival" tabIndex={-1} aria-label="Meniul Casa Mia — alege și comandă"><div className="menu-kind-tabs" role="group" aria-label="Alege meniul"><button aria-pressed={menuKind==='food'} className={menuKind==='food'?'active':''} onClick={()=>setMenuKind('food')}>Mâncare</button><button aria-pressed={menuKind==='drinks'} className={menuKind==='drinks'?'active':''} onClick={()=>setMenuKind('drinks')}>Băuturi</button></div>{menuKind==='food'&&<label className="search"><Search size={20}/><input placeholder="Ce ți-e poftă să mănânci?" value={query} onChange={e=>{setQuery(e.target.value);if(e.target.value)setCategory('Toate categoriile')}} aria-label="Caută în meniu"/>{query&&<button aria-label="Șterge căutarea" onClick={()=>setQuery('')}><X size={16}/></button>}</label>}<FulfillmentChoice compact mode={mode} onChange={setMode}/></div>{menuKind==='food'?<><div className="category-bar"><div className="wrap categories" role="group" aria-label="Categorii meniu">{['Toate categoriile',...categories].map(c=><button key={c} className={category===c?'active':''} aria-pressed={category===c} onClick={()=>{setCategory(c);setQuery('')}}>{c}</button>)}</div></div><div className="wrap"><div className="menu-heading"><h3>{query?'Rezultate pentru „'+query+'”':category}</h3><span>{shown.length} preparate</span></div>{!shown.length?<div className="empty"><Search size={32}/><h3>Pofta asta nu apare în meniu.</h3><p>Încearcă „burger”, „pui” sau „desert”.</p><button className="button dark-button" onClick={()=>{setQuery('');setCategory('Toate categoriile')}}>Vezi toate preparatele</button></div>:<div className="menu-grid">{shown.map(d=><article id={'dish-'+d.id} tabIndex={-1} className={'menu-item'+(heroTarget?.id===d.id?' hero-target':'')} key={d.id}><button className="menu-item-photo" onClick={()=>choose(d)} aria-label={'Vezi '+d.name}><DishPhoto dish={d}/></button><button className="menu-item-main" onClick={()=>choose(d)}><div className="menu-category">{d.category}<span>{d.weight}</span></div><h4>{d.name}</h4>{availability[d.id]!==undefined&&<AvailabilityNote available={availability[d.id]}/>}<p>{d.note||d.ingredients}</p><span className="menu-details">Ingrediente și detalii <ChevronRight size={13}/></span></button><div className="menu-item-bottom"><strong>{money(d.price)}</strong>{cart[d.id]?<div className="quantity compact"><button aria-label={'Scade '+d.name} onClick={()=>change(d.id,-1)}><Minus size={16}/></button><span>{cart[d.id]}</span><button aria-label={'Adaugă '+d.name} onClick={()=>change(d.id,1)}><Plus size={16}/></button></div>:<button className="add-button" disabled={availability[d.id]===false} aria-label={'Adaugă '+d.name} onClick={()=>add(d)}><Plus size={20}/></button>}</div></article>)}</div>}<div className="menu-original-bottom"><button className="underlink" onClick={()=>openOriginal(menuKind==='food'?'restaurant':'bar')}>Vezi meniul original <ArrowUpRight size={18}/></button></div><div className="menu-footnotes"><p>Prețurile sunt exprimate în lei. Pentru alergeni și rețetele complete, solicită informațiile oficiale restaurantului. Preparatele marcate în meniul original cu * pot conține produse congelate.</p><button className="text-button" onClick={openOrders}>Comenzile mele de test <ArrowRight size={16}/></button></div></div></>:<DrinksMenu onOriginal={()=>openOriginal('bar')} onChoose={choose} onAdd={add} cart={cart} onChange={change}/>}</section>
 <section className="story section" id="poveste"><div className="wrap story-grid"><div className="story-art"><img src="./images/casa-mia-logo.webp" alt="Identitatea Casa Mia by OAna: flori, auriu și o masă primitoare" loading="lazy"/><div className="story-art-caption"><span>CASA MIA</span><i>by OAna</i></div></div><div className="story-copy"><p className="eyebrow dark">O INVITAȚIE, CU SUFLET</p><h2>Unele mese<br/>se țin <em>minte.</em></h2><p>Sunt cele la care mai rămâi puțin. La care împarți un platou, descoperi un gust nou și comanzi desert, chiar dacă spuneai că nu mai poți.</p><p>Casa Mia aduce la aceeași masă specialități pregătite cu spectacol, gusturi familiare și preparate din mare. Un meniu pentru zile obișnuite și ocazii care merită sărbătorite.</p><span className="signature">Cu drag, Casa Mia.</span><button className="underlink" onClick={()=>openReserve()}>Hai la o masă bună <ArrowUpRight size={18}/></button></div></div></section>
