.checkout-summary{border-top:1px solid #b2a68b66;padding-top:16px;margin:16px 0}.checkout-summary>div{display:flex;justify-content:space-between;gap:16px;margin:8px 0}.checkout-summary>div:nth-child(4){font-size:20px;padding-top:12px;border-top:1px solid #b2a68b66}.checkout-summary p{font-size:13px;color:#727368}.zone-choice{display:grid;gap:8px;margin:16px 0}.zone-choice select{width:100%;padding:12px;background:#fff;border:1px solid #c8bfae;border-radius:5px;font:inherit}.terms-check{display:flex;align-items:flex-start;gap:10px;font-size:13px;line-height:1.5;margin:20px 0}.terms-check input{width:18px;height:18px;flex:0 0 18px;accent-color:#9b7149;margin-top:2px}.legal-details{display:grid;gap:12px;padding-block:20px;color:#d0c8b4;font-size:12px}.legal-details summary{cursor:pointer;display:list-item}.legal-details p{max-width:900px;line-height:1.6;margin:12px 0}.food-facts{font-size:13px;margin:18px 0}.food-facts dl>div{display:flex;justify-content:space-between;gap:20px;padding:4px 0}.food-facts dd{margin:0}.fulfillment button:disabled{opacity:.4;cursor:not-allowed}
