.service-facts{display:grid;grid-template-columns:1.1fr 1.1fr 1fr;gap:14px;padding:15px 18px;background:linear-gradient(110deg,#eee2ca80,#f6eee180 55%,#ecd7cc50);border-radius:8px}
.service-facts>span{display:flex;align-items:center;gap:10px;min-width:0}
