/* Studio attribution: quiet, legible and native to the Casa Mia palette. */
.studio-signature{display:inline-flex;align-items:center;gap:11px;padding:12px 0;color:#c5ac7c;max-width:100%;transition:color .25s ease}
.studio-signature-mark{width:34px;height:34px;flex-shrink:0;transition:transform .3s ease}
