import {useId,useState,type ReactNode} from 'react';
import {ArrowUpRight,ChevronDown} from 'lucide-react';
import {originalMenus,type EventOffer} from './official';

export default function EventMenuReveal({offer,children}:{offer:EventOffer;children:ReactNode}){
 const [open,setOpen]=useState(false);const contentId=useId();
 return <div className={'event-menu-reveal'+(open?' is-open':'')}>
  <button className="event-preview-trigger" type="button" aria-expanded={open} aria-controls={contentId} aria-label={(open?'Restrânge meniul complet · ':'Vezi meniul complet · ')+offer.subtitle} onClick={()=>setOpen(v=>!v)}>
   <span className="event-preview-art" aria-hidden="true">{originalMenus[offer.id].images.map((file,i)=><img key={file} className={'event-preview-sheet sheet-'+i} src={'./menus/'+file} alt="" width={700} height={990} loading="lazy" decoding="async"/>)}</span>
   <span className="event-preview-caption"><span className="event-preview-kicker">O PRIVIRE ÎN MENIUL TĂU</span><span className="event-preview-title">{open?'Meniul, în detaliu.':'Fiecare detaliu, ales cu grijă.'}</span><span className="event-preview-action">{open?'Restrânge meniul':'Vezi meniul complet'}<ChevronDown size={16}/></span></span>
   <span className="event-preview-corner" aria-hidden="true"><ArrowUpRight size={19}/></span>
  </button>
  <div id={contentId} className="event-reveal-grid" inert={!open} aria-hidden={!open}><div className="event-reveal-clip"><div className="event-reveal-content">{children}</div></div></div>
 </div>
}

