import {useState,useRef,type FormEvent} from 'react';
import {ArrowUpRight,Check,Phone} from 'lucide-react';
import {type EventOffer} from './official';
import {useInquiryService} from './inquiry-client';
export default function EventInquiry({offer,occasion}:{offer:EventOffer;occasion:string}){
 const service=useInquiryService();const [busy,setBusy]=useState(false);const [reference,setReference]=useState('');const [error,setError]=useState('');const [errors,setErrors]=useState<Record<string,string>>({});const form=useRef<HTMLFormElement>(null);
 const title=occasion==='cununie'?'Cununie':occasion==='botez'?'Botez':'Parastas';
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const data=new FormData(e.currentTarget);const v=Object.fromEntries(data.entries());const next:Record<string,string>={};if(String(v.name||'').trim().length<2)next.name='Completează numele tău.';if(!/^\+?[0-9]{9,15}$/.test(String(v.phone||'').replace(/[ ()-]/g,'')))next.phone='Verifică numărul de telefon.';const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Bucharest',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());if(!/^\d{4}-\d{2}-\d{2}$/.test(String(v.date||''))||String(v.date)<today)next.date='Alege o dată de astăzi sau din viitor.';if(!Number.isInteger(Number(v.guests))||Number(v.guests)<1||Number(v.guests)>10000)next.guests='Completează numărul estimat de invitați.';if(!service.demo&&v.terms!=='on')next.terms='Confirmă informarea privind datele personale.';setErrors(next);setError('');const first=Object.keys(next)[0];if(first){form.current?.querySelector<HTMLElement>('[name="'+first+'"]')?.focus();return;}setBusy(true);try{const response=await service.submit({name:String(v.name).trim(),phone:v.phone,date:v.date,guests:Number(v.guests),notes:v.notes||'',occasion,offerId:offer.id==='parastas'?(offer.subtitle.includes('post')?'parastas-post':'parastas-standard'):offer.id,acceptedTerms:v.terms==='on',policyVersion:service.policyVersion});setReference(response.id);}catch(e){setError(e instanceof Error?e.message:'Cererea nu a putut fi salvată. Încearcă din nou sau sună-ne.');}finally{setBusy(false);}}
 const err=(key:string)=>errors[key]?<small id={'inquiry-'+key+'-error'} className="field-error" role="alert">{errors[key]}</small>:null;
 const attr=(key:string)=>({'aria-invalid':!!errors[key],'aria-describedby':errors[key]?'inquiry-'+key+'-error':undefined,onInput:()=>setErrors(e=>({...e,[key]:''}))});
 return <div className="event-inquiry"><div><p className="eyebrow">PLANIFICĂM ÎMPREUNĂ</p><h3>{title}<br/><em>{offer.subtitle}</em></h3><p>{reference?(service.demo?'Ai parcurs formularul demonstrativ.':'Am înregistrat solicitarea. Echipa te va contacta pentru disponibilitate și detalii.'):'Câteva detalii, apoi pregătim împreună evenimentul tău.'}</p><a className="inquiry-phone" href="tel:0761736599"><Phone size={16}/>0761 736 599</a><small>Oana Poteca · Event Manager</small></div>{reference?<div className="inquiry-success" role="status"><span><Check size={26}/></span><h4>{service.demo?'Cerere de test salvată.':'Mulțumim pentru încredere.'}</h4><p>{service.demo?'Nicio cerere nu a fost trimisă restaurantului.':'Data și oferta se confirmă personal. Trimiterea formularului nu reprezintă o rezervare confirmată.'}</p><small>REFERINȚĂ · {reference.slice(0,8).toUpperCase()}</small><a className="button outline-light" href="tel:0761736599">Discută cu Oana <ArrowUpRight size={16}/></a></div>:<form ref={form} onSubmit={submit} noValidate><div className="form-grid"><label>Nume<input name="name" autoComplete="name" required minLength={2} maxLength={80} {...attr('name')}/>{err('name')}</label><label>Telefon<input name="phone" type="tel" autoComplete="tel" required maxLength={24} {...attr('phone')}/>{err('phone')}</label><label>Data evenimentului<input name="date" type="date" min={new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Bucharest',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())} required {...attr('date')}/>{err('date')}</label><label>Număr estimat de invitați<input name="guests" type="number" min={1} max={10000} step={1} required {...attr('guests')}/>{err('guests')}</label><label className="span-2">Observații <span>(opțional)</span><textarea name="notes" maxLength={1000} placeholder="Preferințe, opțiuni suplimentare, ce ai vrea să știm…"/></label></div>{service.demo?<p className="test-note">Formular de prezentare. Folosește date fictive; cererea nu se trimite restaurantului.</p>:<><p className="inquiry-privacy">Folosim numele, telefonul și detaliile evenimentului pentru a răspunde solicitării tale. Datele ajung la echipa Casa Mia.</p><label className="terms-check"><input name="terms" type="checkbox" required {...attr('terms')}/>Am citit informarea privind datele personale din site.</label>{err('terms')}</>}{!service.enabled&&<p className="form-note">{service.error||'Formularul online se pregătește. Discută direct cu Oana la numărul alăturat.'}</p>}{error&&<p className="form-error" role="alert">{error}</p>}<button className="button gold full" disabled={busy||!service.enabled}>{busy?'Se salvează…':service.demo?'Testează solicitarea':'Trimite solicitarea'}<ArrowUpRight size={17}/></button></form>}</div>;
}

