const statuses=['înregistrată','acceptată','în preparare','gata','finalizată'];

function DishPhoto({dish,className='',sizes='(max-width: 767px) 46vw, (max-width: 899px) 31vw, 24vw'}:{dish:Dish;className?:string;sizes?:string}){if(!dish.image)return <BeverageVisual dish={dish}/>;const responsive=dish.image?.startsWith('./images/menu-complete/')&&(dish.imageWidth||0)>480;return <img className={[className,['cm-2','cm-4','cm-108'].includes(dish.id)?'dish-photo-approved':''].filter(Boolean).join(' ')} src={dish.image} srcSet={responsive?dish.image!.replace('.webp','-480.webp')+' 480w, '+dish.image+' '+dish.imageWidth+'w':undefined} sizes={responsive?sizes:undefined} alt={dish.name} loading="lazy" decoding="async" width={dish.imageWidth||640} height={dish.imageHeight||640}/>}

function Modal({title,children,onClose,wide=false,className=''}:{title:string;children:React.ReactNode;onClose:()=>void;wide?:boolean;className?:string}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement;const old=document.body.style.overflow;document.body.style.overflow='hidden';ref.current?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape')onClose();if(e.key==='Tab'){const nodes=ref.current?.querySelectorAll<HTMLElement>('button,a[href],input,select,textarea,[tabindex="0"]');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===ref.current)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',key);previous?.focus();};},[]);return <div className="modal-overlay" onClick={e=>{if(e.target===e.currentTarget)onClose()}}><div ref={ref} className={'modal '+(wide?'wide':'')+' '+className} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1}><div className="modal-head"><span className="eyebrow">CASA MIA BY OANA</span><button className="icon-button" onClick={onClose} aria-label="Închide"><X/></button></div>{children}</div></div>}
export default function Home(){
 const availability=useMenuAvailability();
 const [checkoutDraft,setCheckoutDraft]=useState<CheckoutDraft>(emptyCheckoutDraft);
 const headerRef=useRef<HTMLElement>(null);
 const [eventOccasion,setEventOccasion]=useState<EventOccasion>('cununie');
 const [heroTarget,setHeroTarget]=useState<{id:string}|null>(null);
 const [menuKind,setMenuKind]=useState<'food'|'drinks'>('food');const [originalKind,setOriginalKind]=useState<OriginalKind>('restaurant');
 const [cart,setCart]=useState<Cart>({});const [loaded,setLoaded]=useState(false);const [category,setCategory]=useState('Specialitățile casei');const [query,setQuery]=useState('');const [product,setProduct]=useState<Dish|null>(null);const [qty,setQty]=useState(1);const [panel,setPanel]=useState<'cart'|'reservation'|'orders'|'gallery'|'event-menus'|null>(null);const [mobileNav,setMobileNav]=useState(false);const [step,setStep]=useState(1);const [mode,setMode]=useState('ridicare');const [toast,setToast]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [order,setOrder]=useState<Order|null>(null);const [history,setHistory]=useState<Order[]>([]);const [reserveKind,setReserveKind]=useState('masă');const [reserved,setReserved]=useState(false);
 useEffect(()=>{const banner=document.querySelector<HTMLElement>('.announcement');if(!banner)return;let frame=0;const update=()=>{frame=0;document.documentElement.style.setProperty('--cm-header-top',Math.max(0,banner.getBoundingClientRect().bottom)+'px')};const schedule=()=>{if(!frame)frame=requestAnimationFrame(update)};update();window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);const observer=new ResizeObserver(schedule);observer.observe(banner);return()=>{cancelAnimationFrame(frame);observer.disconnect();window.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule)}} ,[]);
 useEffect(()=>{try{const raw=JSON.parse(localStorage.getItem('cm-preview-cart')||'{}');const clean:Cart={};for(const d of menu){if(Number.isInteger(raw[d.id])&&raw[d.id]>0&&raw[d.id]<=20)clean[d.id]=raw[d.id];}setCart(clean);}catch{}setLoaded(true);},[]);
 useEffect(()=>{if(loaded)localStorage.setItem('cm-preview-cart',JSON.stringify(cart));},[cart,loaded]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),2800);return()=>clearTimeout(timer);},[toast]);
 useEffect(()=>{if(!order?.id)return;const refresh=()=>fetch('/api/orders/'+order.id).then(r=>r.ok?r.json() as Promise<Order>:null).then(d=>{if(d)setOrder(d)}).catch(()=>{});const timer=setInterval(refresh,10000);return()=>clearInterval(timer);},[order?.id]);
 useEffect(()=>{if(!heroTarget)return;const frame=requestAnimationFrame(()=>{const target=document.getElementById('dish-'+heroTarget.id);if(!target)return;target.focus({preventScroll:true});target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});return()=>cancelAnimationFrame(frame);},[heroTarget]);
 function goToHeroDish(d:Dish){setMenuKind('food');setCategory(d.category);setQuery('');setMobileNav(false);setHeroTarget({id:d.id});}
 const lines=menu.filter(d=>cart[d.id]);const count=lines.reduce((n,d)=>n+cart[d.id],0);const total=lines.reduce((n,d)=>n+Math.round(d.price*100)*cart[d.id],0)/100;
 const deliveryEligible=total*100>=serviceRules.deliveryMinimumCents;const payable=cartTotals(Math.round(total*100),mode,count).total/100;
 const shown=foodMenu.filter(d=>(category==='Toate categoriile'||d.category===category)&&normalize(d.name+' '+d.ingredients).includes(normalize(query)));
 function change(id:string,delta:number){if(delta>0&&availability[id]===false)return;setCart(c=>{const n={...c};const q=Math.max(0,Math.min(20,(n[id]||0)+delta));if(q)n[id]=q;else delete n[id];return n;});}
 function add(d:Dish,n=1){if(availability[d.id]===false){setToast('Acest preparat este indisponibil momentan.');return;}setCart(c=>({...c,[d.id]:Math.min(20,(c[d.id]||0)+n)}));setToast(d.name+' — adăugat în coș');}
 function openCart(){setPanel('cart');setStep(1);setError('');setMobileNav(false)}
 function openReserve(kind='masă'){setReserveKind(kind);setReserved(false);setError('');setPanel('reservation');setMobileNav(false)}
 async function openOrders(){setPanel('orders');setError('');setBusy(true);try{const r=await fetch('/api/orders');const data=await r.json() as {orders:Order[];error?:string};if(!r.ok)throw new Error(data.error);setHistory(data.orders);}catch(e){setError(e instanceof Error?e.message:'Nu am putut încărca comenzile.')}finally{setBusy(false)}}
 async function submitOrder(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(mode==='livrare'&&!deliveryEligible){setError('Comanda minimă pentru livrare gratuită este 70 lei în produse.');return;}setBusy(true);setError('');const f=new FormData(e.currentTarget);try{const r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.get('name'),phone:f.get('phone'),mode,address:[f.get('address'),f.get('locality')].filter(Boolean).join(', '),notes:f.get('notes'),items:lines.map(d=>({id:d.id,quantity:cart[d.id]}))})});const data=await r.json() as Order & {error?:string};if(!r.ok)throw new Error(data.error);setOrder(data);setCart({});setStep(3);}catch(e){setError(e instanceof Error?e.message:'Conexiunea a eșuat. Încearcă din nou.')}finally{setBusy(false)}}
 async function submitReservation(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');const f=new FormData(e.currentTarget);try{const r=await fetch('/api/reservations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:f.get('name'),phone:f.get('phone'),date:f.get('date'),time:f.get('time'),guests:Number(f.get('guests')),kind:reserveKind,notes:f.get('notes')})});const data=await r.json() as {id:string;error?:string};if(!r.ok)throw new Error(data.error);setReserved(true);}catch(e){setError(e instanceof Error?e.message:'Nu am putut salva cererea.')}finally{setBusy(false)}}
 function openEventMenus(occasion:EventOccasion='cununie'){setEventOccasion(occasion);setPanel('event-menus');setMobileNav(false)}
 function openOriginal(kind:OriginalKind='restaurant'){setOriginalKind(kind);setPanel('gallery')}
 function choose(d:Dish){setProduct(d);setQty(1);setError('')}
 const goToMenu=useMenuArrival(()=>{setMenuKind('food');setQuery('');setMobileNav(false);setPanel(null);setHeroTarget(null)},menuKind+'|'+category+'|'+query+'|'+loaded+'|'+!!count);
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Bucharest',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 return <>
