');setCategory('Toate categoriile')}}>Vezi toate preparatele</button></div>:<div className="menu-grid">{shown.map(d=><article id={'dish-'+d.id} tabIndex={-1} className={'menu-item'+(heroTarget?.id===d.id?' hero-target':'')} key={d.id}><button className="menu-item-photo" onClick={()=>choose(d)} aria-label={'Vezi '+d.name}><DishPhoto dish={d}/></button><button className="menu-item-main" onClick={()=>choose(d)}><div className="menu-category">{d.category}<span>{d.weight}</span></div><h4>{d.name}</h4>{availability[d.id]!==undefined&&<AvailabilityNote available={availability[d.id]}/>}<p>{d.note||d.ingredients}</p><span className="menu-details">Ingrediente și detalii <ChevronRight size={13}/></span></button><div className="menu-item-bottom"><strong>{money(d.price)}</strong>{cart[d.id]?<div className="quantity compact"><button aria-label={'Scade '+d.name} onClick={()=>change(d.id,-1)}><Minus size={16}/></button><span>{cart[d.id]}</span><button aria-label={'Adaugă '+d.name} onClick={()=>change(d.id,1)}><Plus size={16}/></button></div>:<button className="add-button" disabled={availability[d.id]===false} aria-label={'Adaugă '+d.name} onClick={()=>add(d)}><Plus size={20}/></button>}</div></article>)}</div>}<div className="menu-original-bottom"><button className="underlink" onClick={()=>openOriginal(menuKind==='food'?'restaurant':'bar')}>Vezi meniul original <ArrowUpRight size={18}/></button></div><div className="menu-footnotes"><p>Prețurile sunt exprimate în lei. Pentru alergeni și rețetele complete, solicită informațiile oficiale restaurantului. Preparatele marcate în meniul original cu * pot conține produse congelate.</p><button className="text-button" onClick={openOrders}>Comenzile mele de test <ArrowRight size={16}/></button></div></div></>:<DrinksMenu onOriginal={()=>openOriginal('bar')} onChoose={choose} onAdd={add} cart={cart} onChange={change}/>}</section>
