 const id=useId();
 return <svg className="fulfillment-art luxury-car-art" width={size} height={size} viewBox="0 0 88 56" fill="none" aria-hidden="true" focusable="false"><defs><linearGradient id={id} x1="16" y1="24" x2="68" y2="43" gradientUnits="userSpaceOnUse"><stop stopColor="#ebe0c6"/><stop offset=".45" stopColor="#bca77b"/><stop offset="1" stopColor="#8f7953"/></linearGradient></defs><path d="m8 33 6-5 10-11c2-2 6-3 11-3h14c5 0 9 2 13 6l7 8 9 3c3 1 4 3 4 6v5H6v-5c0-2 0-3 2-4Z" fill={'url(#'+id+')'} stroke="#796846" strokeWidth="1.2" strokeLinejoin="round"/><path d="m23 27 7-9h18c4 0 7 1 10 4l5 5H23Z" fill="#26343a" stroke="#f3e7ce" strokeWidth="1" strokeLinejoin="round"/><path d="m41 18-1 9m11-8 4 8" stroke="#bda87c" strokeWidth="1.3"/><path d="m13 31 10 1 40-1 12 2M38 30l-1 10m24-9 2 9" stroke="#786747" strokeOpacity=".6" strokeWidth=".8"/><path d="M40 33h5m17 0h4" stroke="#f6ead0" strokeWidth="1.2" strokeLinecap="round"/><path d="m8 34 9-1-2 3H8m62-3 9 2v2h-8Z" fill="#fff2c7"/><path d="m7 40 12 1m49 0 12-1" stroke="#f1e5c9" strokeWidth="1.4" strokeLinecap="round"/><circle cx="24" cy="42" r="7.5" fill="#20282b"/><circle cx="66" cy="42" r="7.5" fill="#20282b"/><circle cx="24" cy="42" r="4.1" fill="#b8b6ad" stroke="#e3d8bc" strokeWidth="1"/><circle cx="66" cy="42" r="4.1" fill="#b8b6ad" stroke="#e3d8bc" strokeWidth="1"/><path d="M24 38v8m-4-4h8m38-4v8m-4-4h8" stroke="#555d5d" strokeWidth=".8"/><path d="M33 44h24" stroke="#685f4c" strokeWidth="1.2" strokeLinecap="round"/></svg>;
