import {useEffect,useState} from 'react';
import {Clock,MapPin,Check,ChevronDown} from 'lucide-react';
import {PaperBag,LuxuryCar} from './FulfillmentChoice';
import {cartTotals,serviceRules} from './service-rules';
const price=(n:number)=>(n/100).toLocaleString('ro-RO',{maximumFractionDigits:2})+' lei';
const live=import.meta.env.VITE_COMMERCE_MODE==='live';
export function useMenuAvailability(){const [availability,setAvailability]=useState<Record<string,boolean>>({});useEffect(()=>{if(!live)return;let active=true;const load=()=>window.fetch('./api/index.php?path=catalog',{credentials:'same-origin',cache:'no-store'}).then(r=>r.ok?r.json():null).then(v=>{if(active&&v?.availability)setAvailability(v.availability)}).catch(()=>{});load();const timer=setInterval(load,60000);return()=>{active=false;clearInterval(timer)};},[]);return availability;}
export function AvailabilityNote({available}:{available?:boolean}){return <span className={'availability-note '+(available===false?'unavailable':available===true?'available':'unconfirmed')}><i aria-hidden="true"/>{available===false?'Indisponibil momentan':available===true?'Disponibil':'Disponibilitatea se confirmă la comandă'}</span>}
export function ServiceInfo({mode}:{mode:string}){return <div className="service-info"><div className="service-facts"><span><LuxuryCar size={35}/><span><strong>Livrare gratuită</strong><small>de la 70 lei în produse</small></span></span><span><PaperBag size={29}/><span><strong>Ambalaj · 2 lei</strong><small>o singură dată / comandă</small></span></span><span><Clock size={19} strokeWidth={1.4}/><span><strong>Timp estimat</strong><small>confirmat de restaurant</small></span></span></div><details className="delivery-area"><summary><MapPin size={16}/><span>Bragadiru & împrejurimi <b>· 7 km</b></span><ChevronDown size={15}/></summary><div><p>Livrăm în Bragadiru și împrejurimi, inclusiv în zone din Clinceni și Domnești, în raza de 7 km.</p><p>Adresa exactă se verifică înainte de acceptarea comenzii. Livrare gratuită pentru minimum 70 lei în produse; ambalajul se adaugă separat, 2 lei / comandă.</p></div></details><div className="service-reassurance"><span>{mode==='livrare'?'Livrare la adresa ta':'Ridicare din restaurant'}</span><AvailabilityNote/></div></div>}
export function DeliveryProgress({subtotal,mode,count}:{subtotal:number;mode:string;count:number}){if(!count)return null;const t=cartTotals(Math.round(subtotal*100),mode,count);return <div className={'delivery-progress '+(t.deliveryEligible?'is-qualified':'')} role="status"><div>{t.deliveryEligible?<><Check size={17}/><strong>{mode==='livrare'?'Ai livrare gratuită.':'Poți alege livrarea gratuită.'}</strong></>:<><LuxuryCar size={30}/><span>Mai adaugă <strong>{price(t.remaining)}</strong> pentru livrare gratuită.</span></>}</div><div className="delivery-progress-track" role="progressbar" aria-label="Progres pentru livrare gratuită" aria-valuemin={0} aria-valuemax={70} aria-valuenow={Math.min(70,subtotal)} aria-valuetext={t.deliveryEligible?'Pragul de 70 lei în produse este atins':price(t.remaining)+' până la livrare gratuită'}><span style={{width:Math.min(100,Math.round(subtotal*100/serviceRules.deliveryMinimumCents*100))+'%'}}/></div><details className="cart-delivery-details"><summary>Livrare în Bragadiru & împrejurimi · 7 km</summary><p>Inclusiv zone din Clinceni și Domnești. Adresa se verifică înainte de acceptarea comenzii; timpul estimat se confirmă de restaurant. Pragul de 70 lei se calculează din produse, fără ambalaj.</p></details></div>}
export function OrderTotals({subtotal,mode,count}:{subtotal:number;mode:string;count:number}){const t=cartTotals(Math.round(subtotal*100),mode,count);return <div className="order-price-summary" aria-label="Totalul comenzii"><div><span>Produse</span><strong>{price(t.subtotal)}</strong></div><div><span className="packaging-label"><PaperBag size={23}/>Ambalaj <small>1 / comandă</small></span><strong>{price(t.packaging)}</strong></div>{mode==='livrare'&&<div><span>Livrare</span><strong>{t.deliveryEligible?'Gratuită':'De la 70 lei în produse'}</strong></div>}<div className="grand-total"><span>Total de plată</span><strong>{price(t.total)}</strong></div></div>}

