  resize();window.addEventListener('resize',resize);document.addEventListener('pointerdown',onPointer,{passive:true});
  burst.current=(celebrate)=>{if(preference.matches||document.hidden)return;const focused=document.activeElement?.getBoundingClientRect();const origin=performance.now()-pointer.time<1200?pointer:focused&&focused.width?{x:focused.x+focused.width/2,y:focused.y+focused.height/2}:{x:w*.78,y:h*.55};const colors=['#c6a05a','#e5c482','#b88941','#f0d8a5'];for(let i=0;i<(celebrate?90:16);i++){const angle=Math.random()*Math.PI*2,speed=1.2+Math.random()*2.4;particles.push({x:celebrate?Math.random()*w:origin.x,y:celebrate?-10-Math.random()*h*.35:origin.y,vx:celebrate?(Math.random()-.5)*2:Math.cos(angle)*speed,vy:celebrate?1.7+Math.random()*2.6:-1.6+Math.sin(angle)*speed,angle:Math.random()*Math.PI,spin:(Math.random()-.5)*.15,size:celebrate?3+Math.random()*4:2+Math.random()*3,life:0,duration:celebrate?145:44+Math.random()*15,color:colors[i%colors.length]})}particles=particles.slice(-150);if(!frame){last=performance.now();frame=requestAnimationFrame(draw)}};
