import {useCallback,useEffect,useRef} from 'react';

/** Fit the first complete product row below the fixed masthead, then land there. */
export default function useMenuArrival(onPrepare:()=>void,revision:string){
 const prepare=useRef(onPrepare);prepare.current=onPrepare;
 const measure=useCallback(()=>{
  const section=document.getElementById('meniu'),arrival=document.getElementById('menu-arrival'),grid=section?.querySelector<HTMLElement>('.menu-grid'),header=document.querySelector<HTMLElement>('.header');
  if(!section||!arrival||!grid||!header)return null;
  const clearance=Math.ceil(header.getBoundingClientRect().height+(innerWidth<=560?21:24));
  section.style.setProperty('--menu-clearance',clearance+'px');
  const cards=Array.from(grid.children) as HTMLElement[];if(!cards.length)return {arrival,clearance,overflow:0};
  const firstTop=cards[0].getBoundingClientRect().top;const row=cards.filter(c=>Math.abs(c.getBoundingClientRect().top-firstTop)<2);
  const photo=cards[0].querySelector<HTMLElement>('.menu-item-photo');if(!photo)return null;
  const body=Math.max(...row.map(c=>c.getBoundingClientRect().height-(c.querySelector<HTMLElement>('.menu-item-photo')?.getBoundingClientRect().height||0)));
  const viewport=window.visualViewport?.height||innerHeight;
  const mobileCart=document.querySelector<HTMLElement>('.mobile-cart');const cartHeight=mobileCart&&getComputedStyle(mobileCart).display!=='none'?mobileCart.getBoundingClientRect().height+26:0;
  const reserve=Math.max(16,cartHeight);const top=firstTop-arrival.getBoundingClientRect().top;
  const available=viewport-clearance-top-body-reserve;
  const height=Math.floor(Math.max(60,Math.min(photo.getBoundingClientRect().width,available)));
  if(Math.abs(parseFloat(section.style.getPropertyValue('--menu-photo-height'))-height)>1||!section.style.getPropertyValue('--menu-photo-height'))section.style.setProperty('--menu-photo-height',height+'px');
  return {arrival,clearance,overflow:Math.max(0,60-available)};
 },[]);
 const go=useCallback(()=>{
  prepare.current();
  if(location.hash!=='#meniu')history.pushState(null,'','#meniu');
  requestAnimationFrame(()=>requestAnimationFrame(()=>{const fit=measure();if(!fit)return;fit.arrival.focus({preventScroll:true});window.scrollTo({top:window.scrollY+fit.arrival.getBoundingClientRect().top-fit.clearance+fit.overflow,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
 },[measure]);
 useEffect(()=>{
  const click=(event:MouseEvent)=>{if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const link=(event.target as Element)?.closest<HTMLAnchorElement>('a[href]');if(!link||link.target==='_blank'||link.hasAttribute('download'))return;const url=new URL(link.href,location.href);if(url.origin===location.origin&&url.pathname===location.pathname&&url.hash==='#meniu'){event.preventDefault();go()}};
  const hash=()=>{if(location.hash==='#meniu')go()};document.addEventListener('click',click);window.addEventListener('hashchange',hash);if(location.hash==='#meniu')go();
  return()=>{document.removeEventListener('click',click);window.removeEventListener('hashchange',hash)};
 },[go]);
 useEffect(()=>{
  let frame=0,active=true;const update=()=>{if(!active)return;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{measure()})};
  const resize=()=>{const fit=measure();if(fit&&Math.abs(fit.arrival.getBoundingClientRect().top-fit.clearance)<90)window.scrollTo({top:window.scrollY+fit.arrival.getBoundingClientRect().top-fit.clearance+fit.overflow,behavior:'instant'});update()};
  const observer=new ResizeObserver(update);const section=document.getElementById('meniu');const arrival=document.getElementById('menu-arrival');
  [arrival,document.querySelector('.header'),section?.querySelector('.category-bar'),section?.querySelector('.menu-heading'),...Array.from(section?.querySelectorAll('.menu-item-main')||[]).slice(0,4)].forEach(e=>{if(e)observer.observe(e)});
  update();window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);document.fonts?.ready.then(resize);
  return()=>{active=false;observer.disconnect();cancelAnimationFrame(frame);window.removeEventListener('resize',resize);window.visualViewport?.removeEventListener('resize',resize)};
 },[measure,revision]);
 return go;
}

