import {useState,type ReactNode} from 'react';
import {Plus,Minus,ChevronDown,Check} from 'lucide-react';
import {foodMenu,money,type Dish} from './menu';
import {AvailabilityNote} from './ServiceInfo';

// These original recipes list no included garnish. Never infer this for other dishes.
const separateGarnish=new Set(['Piept de pui la grătar','Somon file la grătar','Mușchi de vită Brazilia']);
const sideNames=['Cartofi aromați la cuptor','Orez basmati','Legume la grătar'];
export default function ProductDetails({dish,photo,facts,available,availability,quantity,onQuantity,onAdd}:{dish:Dish;photo:ReactNode;facts:ReactNode;available?:boolean;availability:Record<string,boolean>;quantity:number;onQuantity:(n:number)=>void;onAdd:(side?:Dish)=>void}){
 const [sideId,setSideId]=useState('');
 const sides=separateGarnish.has(dish.name)?foodMenu.filter(d=>sideNames.includes(d.name)):[];
 const side=sides.find(d=>d.id===sideId);
 const unavailable=available===false||!!side&&availability[side.id]===false;
 return <><div className="product-scroll"><div className="product-visual">{photo}</div><div className="product-body"><div className="product-heading-meta"><span>{dish.category}</span><span>{dish.weight}</span></div><h2>{dish.name}</h2><AvailabilityNote available={available}/>{dish.note&&<p className="product-note">{dish.note}</p>}{dish.raw&&<p className="allergen-note">Acest preparat conține carne sau pește crud.</p>}{dish.frozen&&<p className="allergen-note">Marcat în meniul original ca produs congelat sau cu ingrediente congelate.</p>}
 {dish.ingredients&&<details className="product-detail-section" open><summary>{dish.id.startsWith('bar-')?'Despre această băutură':'Ingrediente'}<ChevronDown size={15}/></summary><p>{dish.ingredients}.</p></details>}
 <details className="product-detail-section"><summary>Alergeni și informații nutriționale<ChevronDown size={15}/></summary>{facts}</details>
 {sides.length>0&&<fieldset className="product-sides"><legend>Îi alegi și o garnitură?</legend><p>Garnitura se comandă separat. Alegerea este opțională.</p><div className="side-options"><label className={!sideId?'selected':''}><input type="radio" name="product-side" checked={!sideId} onChange={()=>setSideId('')}/><span>Doar preparatul</span>{!sideId&&<Check size={13}/>}</label>{sides.map(s=><label key={s.id} className={sideId===s.id?'selected':''}><input type="radio" name="product-side" disabled={availability[s.id]===false} checked={sideId===s.id} onChange={()=>setSideId(s.id)}/><span>{s.name}<small>{s.weight} · +{money(s.price)} / porție{availability[s.id]===false?' · Indisponibilă':''}</small></span>{sideId===s.id&&<Check size={13}/>}</label>)}</div></fieldset>}
 </div></div><div className="product-add product-add-fixed"><div className="quantity"><button aria-label="Scade cantitatea" disabled={quantity<=1} onClick={()=>onQuantity(quantity-1)}><Minus size={18}/></button><span aria-live="polite">{quantity}</span><button aria-label="Crește cantitatea" disabled={quantity>=20} onClick={()=>onQuantity(quantity+1)}><Plus size={18}/></button></div><button className="button dark-button" disabled={unavailable} onClick={()=>onAdd(side)}><span>{unavailable?'Indisponibil momentan':'Adaugă în coș'}</span><strong>{money((dish.price+(side?.price||0))*quantity)}</strong></button>{side&&<small className="product-add-note">Include {quantity} {quantity===1?'porție':'porții'} de {side.name.toLocaleLowerCase('ro-RO')}.</small>}</div></>;
}

