import {useRef,useState,type FormEvent,type ReactNode} from 'react';
import {ArrowRight,ArrowLeft,Check,MapPin,ShoppingBag} from 'lucide-react';
import {OrderTotals} from './ServiceInfo';
import {money} from './menu';
export type CheckoutDraft={name:string;phone:string;locality:string;address:string;postalCode:string;notes:string;payment:string;terms:boolean};
export const emptyCheckoutDraft:CheckoutDraft={name:'',phone:'',locality:'',address:'',postalCode:'',notes:'',payment:'',terms:false};
export function CheckoutSteps({step,onBack}:{step:number;onBack:()=>void}){return <ol className="checkout-steps" aria-label="Pașii comenzii">{['Coș','Detalii','Confirmare'].map((label,i)=><li key={label} className={step===i+1?'current':step>i+1?'complete':''} aria-current={step===i+1?'step':undefined}>{i===0&&step===2?<button onClick={onBack} type="button"><span><Check size={12}/></span>{label}</button>:<><span>{step>i+1?<Check size={12}/>:i+1}</span>{label}</>}</li>)}</ol>}
type Errors=Partial<Record<keyof CheckoutDraft,string>>;
export default function CheckoutDetails({draft,onDraftChange,mode,subtotal,count,lines,isDemo,paymentMethods,legal,busy,error,onSubmit,onBack}:{draft:CheckoutDraft;onDraftChange:(v:CheckoutDraft)=>void;mode:string;subtotal:number;count:number;lines:{id:string;name:string;price:number;quantity:number}[];isDemo:boolean;paymentMethods?:Record<string,string>;legal?:ReactNode;busy:boolean;error:string;onSubmit:(e:FormEvent<HTMLFormElement>)=>void;onBack:()=>void}){
 const form=useRef<HTMLFormElement>(null);const [errors,setErrors]=useState<Errors>({});
 function update<K extends keyof CheckoutDraft>(key:K,value:CheckoutDraft[K]){onDraftChange({...draft,[key]:value});setErrors(e=>({...e,[key]:undefined}));}
 function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const next:Errors={};if(draft.name.trim().length<2||draft.name.trim().length>80)next.name='Scrie numele tău (2–80 de caractere).';if(!/^\+?[0-9]{9,15}$/.test(draft.phone.replace(/[ ()-]/g,'')))next.phone='Verifică numărul de telefon.';if(mode==='livrare'){if(draft.locality.trim().length<2||draft.locality.trim().length>80)next.locality='Completează localitatea.';if(draft.address.trim().length<8||draft.address.length>200)next.address='Completează strada și numărul (minimum 8 caractere).';if(draft.postalCode&&!/^[0-9]{6}$/.test(draft.postalCode))next.postalCode='Codul poștal trebuie să conțină 6 cifre.';}if(!isDemo&&!paymentMethods?.[draft.payment])next.payment='Alege o metodă de plată.';if(!isDemo&&!draft.terms)next.terms='Bifează după ce citești condițiile și informarea.';if(draft.notes.length>500)next.notes='Maximum 500 de caractere.';setErrors(next);const first=Object.keys(next)[0];if(first){form.current?.querySelector<HTMLElement>('[name="'+first+'"]')?.focus();return;}onSubmit(e);}
 const fieldError=(key:keyof CheckoutDraft)=>errors[key]?<small id={'checkout-'+key+'-error'} className="field-error" role="alert">{errors[key]}</small>:null;
 const attributes=(key:keyof CheckoutDraft)=>({'aria-invalid':!!errors[key],'aria-describedby':errors[key]?'checkout-'+key+'-error':undefined});
 return <form ref={form} className="checkout-details" onSubmit={submit} noValidate><button type="button" className="underlink checkout-back" onClick={onBack}><ArrowLeft size={14}/>Înapoi la coș</button>
 {mode==='livrare'&&<fieldset className="checkout-fieldset"><legend><MapPin size={16}/>Unde îți aducem comanda?</legend><div className="form-grid"><label className="span-2">Localitate<input name="locality" autoComplete="address-level2" placeholder="Bragadiru, Clinceni, Domnești…" value={draft.locality} onChange={e=>update('locality',e.target.value)} maxLength={80} required {...attributes('locality')}/>{fieldError('locality')}</label><label className="span-2">Stradă, număr și detalii de acces<input name="address" autoComplete="street-address" placeholder="Strada, numărul, blocul, etajul, apartamentul" value={draft.address} onChange={e=>update('address',e.target.value)} maxLength={200} required {...attributes('address')}/>{fieldError('address')}</label><label className="span-2">Cod poștal <span>(opțional)</span><input name="postalCode" inputMode="numeric" autoComplete="postal-code" value={draft.postalCode} onChange={e=>update('postalCode',e.target.value)} maxLength={6} {...attributes('postalCode')}/>{fieldError('postalCode')}</label></div><p className="delivery-address-note">Livrăm în raza de 7 km din jurul restaurantului. Echipa verifică adresa înainte de acceptarea comenzii.</p></fieldset>}
 <fieldset className="checkout-fieldset"><legend>{mode==='livrare'?'Cum te contactăm?':'Pe ce nume pregătim comanda?'}</legend><div className="form-grid"><label>Nume<input name="name" autoComplete="name" placeholder="Numele tău" value={draft.name} onChange={e=>update('name',e.target.value)} maxLength={80} required {...attributes('name')}/>{fieldError('name')}</label><label>Telefon<input name="phone" type="tel" autoComplete="tel" placeholder="07xx xxx xxx" value={draft.phone} onChange={e=>update('phone',e.target.value)} maxLength={24} required {...attributes('phone')}/>{fieldError('phone')}</label><label className="span-2">Observații <span>(opțional)</span><textarea name="notes" placeholder="Ce ai vrea să știm despre comanda ta?" value={draft.notes} onChange={e=>update('notes',e.target.value)} maxLength={500} {...attributes('notes')}/>{fieldError('notes')}</label></div></fieldset>
 {!isDemo&&<label className="zone-choice">Metoda de plată<select name="payment" value={draft.payment} onChange={e=>update('payment',e.target.value)} required {...attributes('payment')}><option value="">Alege metoda</option>{Object.entries(paymentMethods||{}).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select>{fieldError('payment')}</label>}
 <details className="checkout-items"><summary>Verifică preparatele <span>{count} {count===1?'produs':'produse'}</span></summary>{lines.map(d=><div key={d.id}><span>{d.quantity} × {d.name}</span><strong>{money(d.price*d.quantity)}</strong></div>)}</details><div className="checkout-fulfillment"><ShoppingBag size={16}/><span>{mode==='livrare'?'Livrare la adresa ta':'Ridicare din restaurant'}</span>{isDemo&&<small>Plată la primire · simulare</small>}</div><OrderTotals subtotal={subtotal} mode={mode} count={count}/>
 {isDemo?<p className="test-note">Folosește date fictive. Acesta este un test; comanda nu ajunge la restaurant.</p>:<>{legal}<label className="terms-check"><input name="terms" type="checkbox" checked={draft.terms} onChange={e=>update('terms',e.target.checked)} {...attributes('terms')}/>Am citit condițiile de comandă și informarea privind datele personale.</label>{fieldError('terms')}<p className="form-note">Comanda așteaptă acceptarea restaurantului. Timpul de pregătire se confirmă de echipă.</p></>}
 {error&&<p className="form-error" role="alert">{error}</p>}<button className="button dark-button full" disabled={busy||!count}>{busy?'Se salvează…':isDemo?'Confirmă comanda de test':'Trimite comanda cu obligație de plată'}<ArrowRight size={18}/></button></form>;
}
export function OrderReceipt({order}:{order:{mode?:string;items?:{name:string;price:number;quantity:number}[]}}){return <div className="order-receipt"><p>{order.mode==='livrare'?'Livrare la adresă':'Ridicare din restaurant'}</p>{order.items?.map((d,i)=><div key={i}><span>{d.quantity} × {d.name}</span><strong>{money(d.price*d.quantity/100)}</strong></div>)}</div>}

