/* Focused service details: readable, quiet and accessible on compact screens. */
.modal.product-modal{display:flex;flex-direction:column;overflow:hidden;max-height:92dvh}
.product-modal .modal-head{position:relative;flex-shrink:0}
.product-scroll{min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#cbb58d transparent}
.product-modal .product-visual{height:clamp(210px,34dvh,330px);flex-shrink:0;background:#292825;overflow:hidden}
.product-modal .product-visual img,.product-modal .product-visual img.dish-photo-approved{width:100%;height:100%;aspect-ratio:auto;object-fit:contain;padding:14px}
.product-modal .product-body{padding:24px 30px 26px}
.product-heading-meta{display:flex;justify-content:space-between;gap:20px;font-size:9px;letter-spacing:1px;text-transform:uppercase;color:#8b7655;margin-bottom:10px}
.product-modal .product-body h2{font-size:clamp(27px,3vw,36px);line-height:1.16;letter-spacing:-.7px;margin:0 0 12px}
.product-modal .product-note{font-size:13px;line-height:1.55;margin-bottom:15px;color:#67675e}
.product-detail-section{border-top:1px solid #d5c9b84d;padding:13px 0}
.product-detail-section summary{display:flex;justify-content:space-between;align-items:center;gap:15px;list-style:none;cursor:pointer;font-size:12px;font-weight:500;color:#4f5148}
.product-detail-section summary::-webkit-details-marker{display:none}
.product-detail-section[open] summary>svg{transform:rotate(180deg)}
.product-detail-section summary>svg{color:#9d7c46;transition:transform .2s}
.product-detail-section p,.product-detail-section .allergen-note{font-size:12px;line-height:1.6;margin-top:9px;margin-bottom:0}
.product-add.product-add-fixed{flex-shrink:0;margin:0;padding:17px 28px max(17px,env(safe-area-inset-bottom));display:grid;grid-template-columns:auto 1fr;gap:8px 18px;background:linear-gradient(115deg,#f8f3e7,#fffdf8);border-top:1px solid #d1bd934a;box-shadow:0 -6px 25px #34332a06}
.product-add-fixed .button{width:100%;justify-content:space-between;gap:10px;margin:0;font-size:12px;min-height:49px}
.product-add-fixed .button strong{font-weight:500;white-space:nowrap}
.product-add-fixed .quantity{align-self:center;gap:4px}
.product-add-note{grid-column:1/-1;color:#83704f;font-size:10px;line-height:1.4}
.product-sides,.checkout-fieldset{border:0;margin:14px 0 0;padding:0;min-width:0}
.product-sides legend{font-family:var(--serif);font-size:22px;line-height:1.3;padding:0}
.product-sides>p{font-size:11px;color:#83816f;margin:6px 0 12px;line-height:1.5}
.side-options{display:grid;gap:7px}
.side-options label{display:flex;align-items:center;gap:9px;border:1px solid #d9d1c3;border-radius:4px;padding:10px 12px;font-size:12px;cursor:pointer;line-height:1.4}
.side-options label.selected{border-color:#bba473;background:linear-gradient(110deg,#eee0bd45,#f9f5eb)}
.side-options label:has(input:disabled){opacity:.5;cursor:default}
.side-options label>span{flex:1}.side-options label small{display:block;font-size:10px;color:#827359;margin-top:3px}
.side-options input{accent-color:#8d7345;width:13px;height:13px}.side-options label>svg{color:#8d7345}
.checkout-steps{list-style:none;display:flex;justify-content:space-between;gap:12px;padding:0 0 19px;margin:16px 0 20px;border-bottom:1px solid #d9d1c3}
.checkout-steps li,.checkout-steps button{display:flex;align-items:center;gap:8px;font-size:11px;color:#9b978c;line-height:1.3;padding:0}
.checkout-steps li>span,.checkout-steps button>span{display:grid;place-items:center;width:23px;height:23px;border-radius:50%;border:1px solid #d8ceba;font-size:10px}
.checkout-steps .current{color:#292f2a;font-weight:600}.checkout-steps .current>span{background:#e1c58e;border-color:#e1c58e}
.checkout-steps .complete,.checkout-steps .complete button{color:#8d7446}.checkout-steps .complete span{background:#ede7da;border-color:#d6c8ac}
.checkout-details .checkout-back{margin:0 0 20px;gap:8px}.checkout-fieldset{margin:0 0 24px}
.checkout-fieldset legend{display:flex;align-items:center;gap:8px;padding:0 0 14px;font-family:var(--serif);font-size:21px;color:#333a32;line-height:1.3}
.checkout-details .form-grid{margin:0}.checkout-details .form-grid label,.event-inquiry form label{font-size:11px;color:#585b51}
.checkout-details input,.checkout-details textarea,.checkout-details select,.event-inquiry input,.event-inquiry textarea{background:#fffdf98c;border-color:#d5ccb9;transition:border-color .2s}
.checkout-details [aria-invalid=true],.event-inquiry [aria-invalid=true]{border-color:#aa5e4c}
.field-error{display:block;font-size:10px!important;line-height:1.45;color:#9b4c3a;margin-top:5px;letter-spacing:0;font-weight:400}
.delivery-address-note{margin-top:10px;font-size:11px;line-height:1.6;color:#817557}
.checkout-items{margin-top:20px;border-block:1px solid #dbd2c3;padding:14px 0}
.checkout-items summary{cursor:pointer;font-size:12px;color:#4e5147}.checkout-items summary>span{float:right;font-size:10px;color:#9a8a6c}
.checkout-items>div,.order-receipt>div{display:flex;justify-content:space-between;gap:20px;font-size:11px;line-height:1.5;margin-top:9px}
.checkout-items>div strong,.order-receipt>div strong{font-weight:500;white-space:nowrap}
.checkout-fulfillment{display:flex;align-items:center;gap:8px;font-size:11px;color:#746b59;padding:15px 0 0;flex-wrap:wrap}.checkout-fulfillment small{margin-left:auto;font-size:10px}
.order-receipt{border-bottom:1px solid #d9d1c3;padding:2px 0 18px;margin-bottom:18px}.order-receipt>p{font-size:10px;color:#8a7756;letter-spacing:.8px;text-transform:uppercase;margin-bottom:10px}
.event-quote:has(.event-inquiry){display:block!important;scroll-margin-top:140px}
.event-inquiry{display:grid;grid-template-columns:.85fr 1.15fr;gap:45px}
.event-inquiry>div>p:not(.eyebrow){font-size:12px;line-height:1.7;margin-top:14px;max-width:300px}
.event-inquiry .inquiry-phone{display:flex;align-items:center;gap:9px;font-size:19px;color:#d4b87f;margin-top:24px;white-space:nowrap}.event-inquiry>div>small{display:block;margin-top:6px;font-size:10px;color:#b6ac97}
.event-inquiry form .form-grid{margin:0}.event-inquiry form label>span{color:#8d8778}
.event-inquiry .inquiry-privacy{font-size:10px;line-height:1.6;margin-top:15px;color:#b7ad99}
.event-inquiry .terms-check{font-size:10px;line-height:1.5;color:#d8cbb6;display:flex;align-items:flex-start;gap:9px;margin-top:10px}.event-inquiry .terms-check input{width:15px;height:15px;padding:0;flex-shrink:0;accent-color:#cfb37d}
.event-inquiry .test-note{font-size:10px;line-height:1.6;margin-block:14px 0}
.inquiry-success{display:flex;flex-direction:column;justify-content:center;align-items:flex-start;background:linear-gradient(135deg,#e4ca9112,#dba58b09);border:1px solid #d9bd7d33;border-radius:7px;padding:28px}
.inquiry-success>span{display:grid;place-items:center;width:48px;height:48px;border:1px solid #cbb27b66;border-radius:50%;color:#e2c792;margin-bottom:18px}
.inquiry-success h4{font-family:var(--serif);font-size:27px;font-weight:400;line-height:1.25}.inquiry-success p{font-size:12px;line-height:1.65;margin-top:12px}.inquiry-success>small{font-size:9px;letter-spacing:1px;color:#cbb27c;margin:18px 0}.inquiry-success .button{border-color:#cbb27c55;color:#e9d8b4;font-size:11px}
@media(max-width:650px){.event-inquiry{grid-template-columns:1fr;gap:26px}.event-inquiry .inquiry-phone{margin-top:15px}.product-modal .product-body{padding:19px 22px}.product-add.product-add-fixed{padding:13px 18px max(13px,env(safe-area-inset-bottom));gap:6px 12px}.product-add-fixed .quantity button{width:28px;height:34px}.product-add-fixed .button{font-size:11px;padding:13px 12px}.product-modal .product-visual{height:clamp(180px,30dvh,280px)}.checkout-steps{gap:9px;margin-top:14px}.checkout-steps li,.checkout-steps button{font-size:10px;gap:6px}.checkout-fieldset legend{font-size:20px}.checkout-details input,.checkout-details textarea,.checkout-details select,.event-inquiry input,.event-inquiry textarea{font-size:16px!important}.inquiry-success{padding:23px}}
@media(max-height:550px){.product-modal .product-visual{height:160px}.product-add.product-add-fixed{padding-block:10px}.product-modal .modal-head{padding-block:6px}}
@media(prefers-reduced-motion:reduce){.product-detail-section summary>svg,.checkout-details input,.checkout-details textarea,.checkout-details select,.event-inquiry input,.event-inquiry textarea{transition:none}}
